  "customKeys.title": "Atalhos personalizados",
  "customKeys.intro": "Atribui uma tecla ou combinação de teclas a qualquer comando da pesquisa: uma ferramenta, uma forma, Centrar no plano de trabalho ou o painel de formas. Os teus atalhos ficam guardados neste navegador.",
