  "interactiveHelp.started": "A ajuda interativa está ativa: clica num botão, campo ou janela para saberes mais sobre esse elemento. Prime Esc para sair.",
  "interactiveHelp.ended": "A ajuda interativa está desativada",
  "shortcuts.interactiveHelp": "Ativar ou desativar a ajuda interativa",
  "installHint.chromium": "Instala através do ícone à direita da barra de endereços ou da opção «Instalar como aplicação» no menu do navegador.",
  "installHint.safariMac": "No Safari: menu Ficheiro → «Adicionar à Dock».",
  "installHint.ios": "No Safari: ícone de partilha → «Adicionar ao ecrã principal».",
  "installHint.firefox": "O Firefox não permite instalar aplicações, mas o layerling continua a abrir sem internet neste separador.",
  "welcome.moreLanguagesTitle": "O teu idioma",
  "welcome.moreLanguagesBody": "o programa e o respetivo guia estão disponíveis em inglês, alemão e mais 18 idiomas. A lista de idiomas encontra-se no canto superior direito e nas definições da página inicial.",
  "welcome.moreOfflineTitle": "Funciona sem internet",
  "welcome.moreOfflineBody": "após a primeira visita, o layerling também abre sem internet. Instala-o como um programa normal; os teus projetos ficam no teu computador.",
  "welcome.moreAiTitle": "Modelar com IA",
  "welcome.moreAiBody": "através da interface MCP, um assistente de IA pode criar e editar formas num editor que ele próprio abre. Para isso, precisas de executar uma cópia por tua conta (npm run dev ou a imagem Docker). Em layerling.com, a ligação à IA está desativada.",
  "welcome.morePointsTitle": "Pontos de referência",
  "welcome.moreSearchTitle": "Pesquisa de comandos",
  "welcome.moreSimplifyTitle": "Simplificar malhas",
  "welcome.moreSimplifyBody": "Uma malha importada com um número muito elevado de triângulos pode ser reduzida a uma fração desse número, com uma vista de comparação e um controlo deslizante, para manter a fluidez ao cortar, agrupar e arrastar.",
  "welcome.moreHistoryTitle": "Histórico",
  "welcome.moreLookTitle": "Aspeto ao teu gosto",
  "welcome.moreLookBody": "Nas definições, podes ajustar o fundo e o plano de trabalho, as setas dos eixos X, Y e Z, as linhas das arestas de cada sólido, as cores dos esboços, o contraste, as sombras e a direção da luz, por exemplo para distinguir melhor os sólidos escuros entre si. Em computadores mais lentos, o modo rápido desativa de uma só vez todos os efeitos que exigem mais recursos.",
  "welcome.moreControlsTitle": "Rato e rato 3D",
  "welcome.moreControlsBody": "permite configurar os botões do rato para funcionarem como no Bambu Studio e no OrcaSlicer: arrastar com o botão esquerdo num espaço vazio roda a vista e o botão direito desloca-a. Também permite controlar a vista com um SpaceMouse no Chrome e no Edge.",
  "welcome.moreTabletTitle": "No tablet",
  "welcome.moreTabletBody": "um dedo trabalha no desenho como o botão esquerdo do rato, dois dedos fazem zoom e deslocam a vista; um teclado Bluetooth traz os atalhos.",
  "welcome.moreHistoryBody": "consultar qualquer estado anterior do projeto com um controlo deslizante, sem alterar nada. Podes exportar esse estado, criar um novo projeto a partir dele ou recuperar objetos individuais.",
  "welcome.moreDrawingTitle": "Desenho técnico para a oficina",
  "welcome.moreDrawingBody": "Exportar → Desenho: vistas de frente, de cima e de lado à escala 1:1 numa folha de formato ISO, com dimensões gerais, arestas ocultas e uma tabela dos furos circulares. Disponível em PDF ou SVG, para imprimir ou levar para o torno e a fresadora.",
  "welcome.moreSearchBody": "Prime Ctrl+K e escreve o nome de uma ferramenta, forma ou comando para lhe acederes diretamente, em inglês ou alemão, com os atalhos de teclado apresentados ao lado de cada opção. Também podes encontrar os sólidos do teu projeto pelo nome. Também podes atribuir um atalho personalizado a qualquer um deles.",
  "welcome.moreHelpTitle": "Ajuda interativa",
  "welcome.moreHelpBody": "carrega em Shift+F1 ou no ponto de interrogação e clica em qualquer botão, campo ou janela: uma pequena janela mostra a parte do guia sobre ele.",
  "welcome.morePointsBody": "clicar com o botão direito num sólido para assinalar o centro, os vértices ou os pontos médios das arestas com pontos de referência que não são impressos e aos quais as formas se ajustam. Assim, podes colocar um furo exatamente no centro de outra peça.",
  "welcome.videosTitle": "Vídeos sobre o layerling",
  "welcome.videosHint": "Criados por terceiros, sem ligação a este projeto. As ligações abrem o YouTube num novo separador; nenhum conteúdo desse site é carregado até clicares.",
  "welcome.help": "No editor, o grupo Ajuda inclui um breve guia e a lista de todos os atalhos de teclado. No rodapé, a opção «Reportar um erro» guarda o teu projeto com todos os elementos necessários para comunicar o problema no fórum ou no GitHub.",
  "welcome.guideLink": "Ler o guia do utilizador completo, com imagens",
  "welcome.guideUrl": "/guia-pt-pt/index.html",
  "guide.helpLink": "Ler sobre este assunto no guia do utilizador",
