  "confirm.openWithoutHistoryBody": "{name} abre no estado atual. Todos os passos anteriores que permitem anular ações são eliminados permanentemente, pelo que Anular não poderá recuar para além deste ponto. Esta opção ajuda quando um projeto abre muito lentamente ou não abre.",
