  "cookieCutter.help": "O contorno da seleção transforma-se numa parede fina com uma aresta de corte e uma aba plana em redor da base. Os furos, como o interior de um e, recebem paredes próprias. A parede, a altura e a aba podem ser alteradas posteriormente em Propriedades.",
