  "cable.minWall": "Espessura mínima da parede",
  "cable.hint": "Um cabo consegue passar por uma curva com um raio de cerca de cinco vezes o seu diâmetro. O canal é criado como um tubo curvo usado como forma de corte, agrupado com o sólido, e pode ser alterado posteriormente.",
  "cable.working": "A procurar um trajeto …",
