  "cable.tight": "Uma curva tem um raio inferior ao pedido: não há espaço no sólido para uma curva mais suave nesse local. Reduz o valor de Raio mínimo de curvatura ou escolhe outra entrada ou saída.",
  "cable.thin": "A parede é mais fina do que o pedido num dos locais.",
  "cable.error.needsBody": "Seleciona um sólido para criar o canal para cabos.",
