  "cable.error.endsTooClose": "A entrada e a saída estão demasiado próximas.",
  "cable.error.endTooThin": "Na entrada ou na saída, o sólido é demasiado fino para este diâmetro e esta espessura de parede.",
  "cable.error.noWay": "Não foi encontrado nenhum trajeto que mantenha a espessura da parede. Um diâmetro menor ou uma parede mais fina poderá permitir a passagem.",
  "cable.error.tooWinding": "O trajeto precisa de mais curvas do que as disponíveis num tubo curvo (11). Escolhe outro local para a entrada ou a saída.",
  "cable.error.kernel": "Não foi possível abrir o canal no sólido.",
  "cable.apply": "Criar canal",
