  "lid.error.tooSmall": "A abertura é demasiado pequena para um bordo interior com esta folga. Reduz a folga ou escolhe uma tampa plana.",
  "lid.error.tooShallow": "O bordo interior ou exterior é mais profundo do que a altura do sólido. Reduz a profundidade.",
