  "lid.magnetGap": "Folga em redor do íman",
  "lid.magnetsHint": "Alojamentos nos cantos do sólido e da tampa, com pilares onde a parede é demasiado fina. Usa uma folga de 0,1 mm para encaixar os ímanes à pressão ou uma folga maior para os colar. Mais informações no guia.",
  "lid.magnetsThicknessRaised": "Espessura da tampa aumentada para {thickness} mm para acomodar os ímanes.",
  "lid.magnetPosts": "Pilares para ímanes de {name}",
