  "lid.error.magnetsThinLid": "A tampa é demasiado fina para estes ímanes: aumenta a espessura para pelo menos {thickness} mm.",
  "lid.error.magnetsBundle": "Um conjunto não é um único sólido. Agrupa-o primeiro e depois cria a tampa com ímanes.",
