  "punch.axisHint": "X vai da esquerda para a direita, Y da frente para trás e Z para cima. O layerling começa pela direção em que o punção está mais afastado do sólido.",
  "punch.clearance": "Folga",
  "punch.clearanceHint": "Quanto a abertura excede o contorno em cada lado. 0 segue-o exatamente; 0,2 mm permite a passagem de uma peça impressa.",
