  "editor.tool.offset": "Desfasamento das faces",
  "offset.title": "Desfasamento das faces do sólido",
  "offset.subtitle": "Todas as faces deslocadas pela mesma distância",
  "offset.help": "Expande ou contrai o sólido deslocando as suas faces. Para criar a folga de um encaixe à pressão, expande-o e mantém-no como forma de corte.",
  "offset.direction": "Direção",
  "offset.grow": "Expandir",
