  "offset.distance": "Distância",
  "offset.edges": "Cantos exteriores",
  "offset.edgesHint": "Arredondados mantém a superfície desfasada arredondada nos cantos exteriores; Vivos prolonga as faces até se encontrarem.",
  "offset.copy": "Manter o original e adicionar o sólido desfasado como forma de corte",
  "offset.sideways": "Apenas os lados: o topo e a base planos mantêm a altura",
  "offset.apply": "Aplicar desfasamento",
  "offset.working": "A aplicar desfasamento…",
  "offset.cancel": "Cancelar desfasamento",
  "offset.errorFailed": "Não foi possível expandir ou contrair o sólido por esta distância. Escolhe uma distância mais pequena.",
  "status.offsetGrown": "Expandido em {size} mm",
  "status.offsetShrunk": "Contraído em {size} mm",
  "status.offsetCopy": "Sólido adicionado como forma de corte, com um desfasamento de {size} mm",
  "status.offsetMcp": "O MCP aplicou um desfasamento de {size} mm ao objeto",
  "edge.revertOffset": "Desfasamento ({size} mm)",
  "historyStep.offsetOne": "Desfasamento de {name}",
  "historyStep.offsetMany": "Desfasamento de {count} objetos",
  "guide.edges.offset": "O desfasamento desloca todas as faces de um sólido pela mesma distância, para fora ou para dentro. Expande uma cópia e mantém-na como forma de corte para obter a folga de um encaixe à pressão, ou contrai um sólido para criar um pino que tenha de entrar num furo. Muitas vezes, não é possível aplicar desfasamento a sólidos constituídos apenas por uma malha de triângulos.",
  "edge.revertSurfaceTexture": "Textura de superfície ({size} mm de profundidade)",
  "deleteFace.title": "Eliminar face",
  "deleteFace.subtitle": "As faces adjacentes preenchem o espaço",
  "deleteFace.help": "Clica nas faces a eliminar; volta a clicar numa face para a retirar da seleção. As faces adjacentes prolongam-se até preencherem o espaço: o arredondamento, o furo ou a saliência desaparece, e o sólido mantém a geometria exata. As faces finas como um cabelo entre faces do mesmo plano são eliminadas juntamente com as faces selecionadas.",
  "deleteFace.preparing": "A ler as faces…",
  "deleteFace.countNone": "Ainda nenhuma face selecionada",
  "deleteFace.countOne": "1 face selecionada",
  "deleteFace.countMany": "{count} faces selecionadas",
  "deleteFace.thinOne": "Incluída também: 1 face fina como um cabelo",
  "deleteFace.thinMany": "Incluídas também: {count} faces finas como um cabelo",
  "deleteFace.apply": "Eliminar",
  "deleteFace.working": "A eliminar faces…",
  "deleteFace.cancel": "Cancelar eliminação de faces",
  "deleteFace.errorUnchanged": "Não é possível eliminar estas faces: as faces adjacentes não conseguem preencher o espaço. Seleciona todas as faces do elemento a remover, como todas as faces de um arredondamento ou toda a parede de um furo, sem selecionar faces do restante sólido.",
  "deleteFace.errorMesh": "Este sólido não tem faces de geometria exata que possam ser eliminadas: o layerling mantém-no como malha, tal como acontece com um STL, OBJ ou 3MF importado, um sólido dividido, aplicado a uma superfície curva ou simplificado, ou uma forma muito detalhada, como um texto longo. Uma peça importada em STEP tem faces de geometria exata.",
  "deleteFace.errorResized": "Este sólido foi redimensionado com a opção «Manter dimensões das arestas ao redimensionar» ativa, pelo que as suas faces de geometria exata já não correspondem às suas dimensões. Anula o redimensionamento, elimina as faces e volta a redimensionar.",
  "deleteFace.errorProjectChanged": "O objeto ou o projeto foi alterado durante a eliminação das faces. Tenta novamente.",
  "deleteFace.errorFailed": "Não foi possível eliminar as faces. Seleciona outras faces.",
  "deleteFace.errorNoFaces": "Não foi possível ler as faces deste sólido. Fecha a ferramenta e volta a abri-la.",
  "deleteFace.errorTooSlow": "A eliminação destas faces demorou demasiado e foi interrompida após 45 segundos. Nada foi alterado. O núcleo CAD não consegue processar estas faces nesta peça: seleciona outras faces ou um número menor.",
  "status.facesDeletedOne": "1 face eliminada",
  "status.facesDeletedMany": "{count} faces eliminadas",
  "status.facesDeletedMcpOne": "O MCP eliminou 1 face",
  "status.facesDeletedMcpMany": "O MCP eliminou {count} faces",
  "status.deleteFaceCancelled": "Eliminação de faces cancelada",
  "status.deleteFaceCancelledChanged": "Eliminação de faces cancelada porque o objeto foi alterado",
  "edge.revertDeleteFaceOne": "Faces eliminadas (1 face)",
  "edge.revertDeleteFaceMany": "Faces eliminadas ({count} faces)",
