  "status.paintTooMany": "Este sólido tem {count} pinceladas, o máximo permitido. Usa Limpar tudo para recomeçar.",
  "paint.wholeFaces": "Esta malha não está fechada: os círculos e os laços seguem os respetivos triângulos.",
  "status.honeycombConverted": "Estrutura em favo de mel convertida num padrão de furos: {count}",
  "welcome.moreHolePatternTitle": "Padrão de furos",
  "welcome.moreHolePatternBody": "Clica numa face plana de um sólido e distribui furos por ela: circulares, quadrados, retangulares, hexagonais ou ranhuras, numa grelha ou em filas desfasadas, com espaçamento, margem até ao bordo e profundidade ajustáveis (atravessando todo o sólido ou até uma profundidade definida). A pré-visualização mostra os furos antes de os criares; continuam a ser formas de corte normais, agrupadas com o sólido, para criar aberturas de ventilação, grelhas de altifalantes, cestos e caixas. Também podes distribuir furos para parafusos ao longo do contorno, com um furo em cada canto e rebaixos cilíndricos ou escareados, se quiseres. Uma forma personalizada pode ser repetida da mesma maneira, como rebites ou um padrão de chapa xadrez. Na parede redonda de um cilindro ou tubo, os furos distribuem-se em toda a volta, cada um orientado para o eixo.",
  "welcome.moreSupportRibTitle": "Nervura de suporte",
  "welcome.moreSupportRibBody": "Imprime uma peça inclinada sobre uma aresta sem os suportes do fatiador: clica na face inferior e uma nervura fina fica por baixo, a pequena distância, sobre um pé oval, com pontes minúsculas de exatamente uma camada que seguram a peça e depois se partem.",
  "welcome.moreStencilBridgesTitle": "Pontes de stencil",
  "welcome.moreStencilBridgesBody": "Imprime um stencil com texto vazado: o miolo de letras como o, a e b ganha pequenas pontes até à placa, tão largas e altas quanto quiseres, para que nada caia.",
  "welcome.moreFaceTitle": "Empurrar uma face",
  "welcome.moreFaceBody": "puxa uma face plana de um corpo para fora ou corta uma caixa nela, com recuo a partir da aresta, cantos arredondados e profundidade, em pré-visualização - também em STL importados.",
  "welcome.moreTextureTitle": "Textura de superfície",
  "welcome.moreTextureBody": "aplica um relevo a qualquer sólido, para melhorar a aderência ou o aspeto: recartilhado, ranhuras, favo de mel, tijolos, fibra de carbono, casca de árvore, veios de madeira, corda, uma imagem como mapa de alturas ou texto, em redor de sólidos arredondados ou numa projeção plana ao longo de um eixo. Um sólido pode ter até seis padrões, cada um nas suas próprias faces. Para impressão em duas cores, o padrão também pode tornar-se uma peça independente, com a sua própria cor.",
  "welcome.moreVaseTitle": "Vasos e recipientes",
  "welcome.moreVaseBody": "uma forma própria para vasos, recipientes e abat-jours: formato do sólido, secção transversal, torção, padrões, furos de drenagem, prato e tampa. Pode ser maciça, para o modo vaso do programa de preparação da impressão, ou oca. Uma tampa de bule usa o próprio topo do vaso, mantendo a continuidade do padrão através da união.",
  "welcome.moreOffsetTitle": "Desfasamento e recorte",
  "welcome.moreOffsetBody": "expande ou contrai um sólido exato por uma distância definida, em toda a volta ou apenas lateralmente, para criar a folga de um encaixe à pressão. Também permite recortar uma peça a partir de outra com uma folga em toda a volta, numa única operação.",
  "welcome.morePunchTitle": "Puncionar",
  "welcome.morePunchBody": "recorta o contorno de um sólido em linha reta através de outro, a partir da posição em que se encontra à sua frente: a silhueta de um bule através de uma placa ou um logótipo através de uma tampa. Move ou roda o punção e volta a puncionar; uma folga permite a passagem de uma peça impressa.",
  "welcome.moreClearanceTitle": "Verificar folgas",
  "welcome.moreClearanceBody": "antes de imprimir peças que devem mover-se, como uma dobradiça impressa sem montagem, um brinquedo articulado ou uma tampa na respetiva caixa, deteta os pares que se sobrepõem, se tocam ou estão mais próximos do que a folga definida.",
  "guide.select.holePattern": "Padrão de furos (botão da faixa de ferramentas junto a Padrão, clique com o botão direito num sólido ou Ctrl+K): clica numa face plana ou numa parede redonda e define a forma dos furos, o tamanho, o espaçamento, a disposição, a margem e a profundidade. Os furos aparecem numa pré-visualização; \"Criar\" adiciona-os como formas de corte agrupadas com o sólido. Desagrupar volta a separá-los.",
  "guide.select.faceTool": "Face (botão do friso junto a Padrão de furos, clique com o botão direito num sólido ou Ctrl+K): clica numa face plana, escolhe Para fora ou Para dentro e define o recuo a partir do bordo, o raio dos cantos e a profundidade. O resultado é um sólido criado a partir de um esboço, agrupado com o sólido original.",
  "guide.select.supportRib": "Nervura de suporte (botão do friso, clique com o botão direito num sólido ou Ctrl+K): clica na face inferior de uma peça impressa inclinada sobre uma aresta. Uma nervura fina fica por baixo a pequena distância, sobre um pé oval, presa à peça por pequenas pontes com uma camada de altura; define o bico e as camadas do teu fatiador.",
  "scalePercent.errorTooSmall": "\"{name}\" ficaria com uma dimensão inferior a 0,01 mm.",
  "scalePercent.errorTooLarge": "\"{name}\" ficaria maior do que a forma permite. Aumenta o \"Limite de tamanho personalizado\" em Predefinições das formas, nas definições, ou escolhe uma percentagem menor.",
