  "gear.involuteHint": "Diâmetro primitivo de {pitch} mm. Engrena com qualquer engrenagem de módulo {module}; distância entre centros = (número de dentes de uma + número de dentes da outra) × módulo / 2.",
  "gear.profileRound": "Arredondado",
  "gear.roundHint": "Dentes arredondados formados por arcos, mais fáceis de imprimir em engrenagens pequenas e com uma superfície de contacto suave em manípulos. Diâmetro primitivo de {pitch} mm. Engrena com qualquer engrenagem de dentes arredondados de módulo {module}; distância entre centros = (número de dentes de uma + número de dentes da outra) × módulo / 2.",
  "gear.simpleHint": "Dentes de perfil reto para fins visuais. Para duas engrenagens que engrenem corretamente, escolhe Evolvente.",
  "gear.internal": "Coroa de dentado interior",
