  "gear.internalHint": "Dentes voltados para dentro. Diâmetro primitivo de {pitch} mm. Uma engrenagem de módulo {module} roda no seu interior; distância entre centros = (número de dentes da coroa − número de dentes da engrenagem) × módulo / 2.",
  "gear.internalRoundHint": "Dentes arredondados voltados para dentro. Diâmetro primitivo de {pitch} mm. Uma engrenagem de dentes arredondados de módulo {module} roda no seu interior; distância entre centros = (número de dentes da coroa − número de dentes da engrenagem) × módulo / 2.",
  "gear.rackHint": "Passo de {pitchLength} mm por dente; o comprimento é o número de dentes × passo. Uma engrenagem de módulo {module} engrena com a cremalheira: a distância do centro da engrenagem à linha primitiva é o respetivo número de dentes × módulo / 2. A linha primitiva fica {offset} mm atrás das pontas dos dentes.",
  "gear.rackRoundHint": "Dentes arredondados, com passo de {pitchLength} mm por dente; o comprimento é o número de dentes × passo. Uma engrenagem de dentes arredondados de módulo {module} engrena com a cremalheira: a distância do centro da engrenagem à linha primitiva é o respetivo número de dentes × módulo / 2. A linha primitiva fica {offset} mm atrás das pontas dos dentes.",
