  "thread.flankAngleHint": "Ângulo entre os dois flancos de um dente. 60° corresponde à rosca em V de vértice vivo e 30° à rosca trapezoidal. Com 90° ou menos, nenhum flanco fica a menos de 45° da horizontal, permitindo imprimir a rosca sem suportes.",
  "thread.startsHint": "Filetes lado a lado, como num fuso de avanço: um T8x8 tem 4 entradas com passo de 2 mm. 1 corresponde a uma rosca normal.",
