  "prop.threadChamferBottom": "Chanfro na extremidade inferior",
  "thread.axialClearanceHint": "Folga adicional ao longo da rosca, em mm, além da folga diametral: cada dente da porca fica mais fino neste valor, mantendo o diâmetro. Para uma rosca que rode livremente sem abanar lateralmente, mantém a folga diametral entre 0,2 e 0,3 e define 0,2 aqui. Com 0, a folga resulta apenas da folga diametral, que abre os flancos em cerca de metade desse valor.",
  "thread.clearanceHint": "Espaço adicional no diâmetro total. Uma rosca impressa precisa de mais folga do que parece: o espaço entre os flancos é apenas cerca de metade deste valor. Cerca de 0,3 dá um ajuste apertado, 0,4 um ajuste normal e 0,5 um ajuste folgado. Imprime primeiro um par de teste.",
  "thread.boltClearanceHint": "Reduz o diâmetro do parafuso neste valor para usar uma porca metálica sem folga própria (0,3 a 0,4, tal como a folga de uma porca impressa). Com uma porca impressa, mantém este valor em 0 e aplica a folga na porca.",
