  "inspector.surfaceCrackSeed": "Semente",
  "inspector.surfaceCrackSeedHint": "A mesma semente produz as mesmas fissuras; outro valor gera uma nova disposição. O comprimento é medido em percentagem da altura ou, do bordo para o meio, em percentagem do raio.",
  "inspector.surfaceCrackGold": "Preenchimento dourado como peça independente",
  "inspector.surfaceCrackRecess": "Recuo do preenchimento dourado",
  "inspector.surfaceCrackGoldHint": "O preenchimento das fissuras torna-se uma peça independente dourada, para um segundo filamento; o topo fica esta distância abaixo da superfície. Para isso, o padrão é aplicado para dentro do sólido.",
  "inspector.surfacePatternPart": "Padrão como peça independente",
  "inspector.surfacePatternColor": "Cor do padrão",
  "inspector.surfacePatternRaisedHint": "A parte saliente do sólido torna-se uma peça independente nesta cor, para um segundo filamento; o sólido original mantém-se. Ambos ficam reunidos num conjunto: movem-se em conjunto e a textura continua a poder ser alterada ou removida.",
  "inspector.surfacePatternCutHint": "A parte escavada no sólido torna-se uma peça independente nesta cor, preenchendo o recorte até à superfície, para um segundo filamento. Ambos ficam reunidos num conjunto: movem-se em conjunto e a textura continua a poder ser alterada ou removida.",
  "inspector.surfacePatternWayHint": "Apenas para um padrão aplicado para fora ou para dentro do sólido, no mesmo sentido em todas as camadas: com as definições atuais, o padrão mantém-se integrado no sólido.",
  "status.surfaceNoCracks": "Nenhuma fissura encontrou um trajeto neste sólido. Experimenta outro início (\"Qualquer ponto\" funciona em qualquer sólido), fissuras mais compridas ou permite que o padrão alcance mais faces.",
  "status.surfaceCracks": "{count} linhas de fissura, com {length} mm no total.",
  "status.surfaceGold": "O preenchimento dourado ocupa as fissuras como uma peça independente.",
  "status.surfacePatternRaised": "O padrão é uma peça independente, reunida num conjunto com o sólido original.",
  "status.surfacePatternCut": "O recorte é preenchido por uma peça independente, reunida num conjunto com o sólido.",
  "status.surfacePatternOneBody": "O padrão mantém-se integrado no sólido: para ser uma peça independente, tem de ser aplicado para fora ou para dentro do sólido, no mesmo sentido em todas as camadas.",
