  "surfaceTexture.carbonTwill31": "Sarja 3/1",
  "surfaceTexture.carbonTwill22Hint": "Cada faixa passa por cima de duas faixas transversais e por baixo de outras duas: a diagonal regular da maioria das peças de fibra de carbono.",
  "surfaceTexture.carbonTwill21Hint": "Por cima de duas e por baixo de uma: as faixas verticais apresentam troços longos e as transversais troços curtos.",
  "surfaceTexture.carbonTwill31Hint": "Por cima de três e por baixo de uma: faixas verticais longas, com as transversais visíveis apenas em pequenos troços entre elas.",
  "inspector.surfaceCarbonCross": "Largura das faixas transversais",
  "inspector.surfaceCarbonHint": "Largura das faixas transversais a 0: igual à das faixas verticais. Uma largura maior ou menor cria um entrelaçamento desigual. Em redor de um sólido, a largura é ligeiramente ajustada para fechar o padrão.",
  "inspector.surfaceSeed": "Disposição",
  "inspector.surfaceSeedHint": "Outro número gera uma nova disposição das células ou dos grãos.",
  "inspector.surfaceImage": "Imagem",
  "inspector.surfaceImageLoad": "Carregar imagem personalizada…",
  "inspector.surfaceImageHint": "As zonas claras atingem a profundidade máxima e as escuras mantêm-se inalteradas. Um desenho escuro sobre fundo transparente, como linhas pretas num SVG, é interpretado pelas linhas, que atingem a profundidade máxima. A imagem personalizada é guardada com o projeto em tons de cinzento, com um máximo de 512 pontos por lado; cada módulo tem a largura definida e uma altura proporcional à imagem.",
  "inspector.surfaceTileHeight": "Altura do módulo (0 = proporcional à imagem)",
  "inspector.surfaceImageHeight": "Altura da imagem",
  "inspector.surfaceImageOnceHint": "A imagem é aplicada uma única vez, como uma etiqueta: Posição angular e Altura definem o centro, como no texto. Fora da imagem, a superfície mantém-se lisa; Profundidade e Direção definem quanto fica saliente ou escavada. Uma altura de imagem de 0 mantém as proporções originais. Quando há faces selecionadas, a imagem é sempre aplicada sobre elas.",
  "inspector.surfaceImageTurn": "Rotação (°)",
  "inspector.surfaceImageInvert": "Trocar claro e escuro",
  "inspector.surfaceImageBlur": "Suavização",
  "inspector.surfaceImageTiling": "Repetição",
  "inspector.surfaceGrainHint": "O granulado é definido no espaço em vez de ser projetado: sem uniões nem esticamentos, mantendo o mesmo aspeto em qualquer forma.",
