  "surfaceTexture.woodCutLogHint": "A medula percorre o centro do sólido: as extremidades mostram os anéis de crescimento e os lados mostram os veios de um tronco sem casca.",
  "surfaceTexture.woodCutFlatSawnHint": "A medula passa por baixo da tábua, ao longo do lado mais comprido: os anéis intersectam a face em arcos.",
