  "inspector.surfaceTimberGrainHint": "0 %: sem veios. Abaixo de 50 %, mais finos: mais sulcos, mais estreitos e menos profundos. Acima de 50 %, mais marcados: dois sulcos largos e profundos. 50 %: configuração inicial.",
  "inspector.surfaceTimberHint": "A largura dos painéis, de pilar a pilar, e a altura dos pisos são ligeiramente ajustadas para caberem painéis completos: em redor de um sólido redondo, de uma aresta à outra de um lado plano e a partir da aresta inferior. As vigas ficam salientes e o reboco entre elas fica rebaixado.",
