  "vaseCheck.slitsKept": "Programa de preparação da impressão: ativa o modo vaso em espiral e define a largura da linha exterior para {line} mm, como aqui. As fendas de {slit} mm são mantidas com as predefinições; as duas linhas de uma nervura ficam separadas por {slit} mm. Para as unir firmemente, usa uma largura de fenda de 0,03 mm e define \"Slice gap closing radius\" para 0,01 mm no programa de preparação da impressão (PrusaSlicer, OrcaSlicer, Bambu Studio).",
  "vaseCheck.slitsGap": "Programa de preparação da impressão: ativa o modo vaso em espiral e define a largura da linha exterior para {line} mm, como aqui. Importante: define \"Slice gap closing radius\" (PrusaSlicer, OrcaSlicer, Bambu Studio) para um máximo de {radius} mm; caso contrário, o programa fecha as fendas de {slit} mm e imprime uma parede simples.",
