  "export.stl.description": "Malha para impressão 3D",
  "export.stl.note": "Ideal para programas de preparação da impressão e impressão 3D. A geometria é exportada como uma malha de triângulos. No Chrome e no Edge, escolhes a pasta e o nome uma vez; as exportações STL seguintes do projeto são guardadas nesse ficheiro, a menos que introduzas outro nome, caso em que voltará a ser pedido um ficheiro.",
  "export.stlLinkedFile": "Guarda em {name}",
  "export.stlNewFile": "Pede onde guardar {name}",
  "export.stlSaveAs": "Guardar como…",
  "export.3mf.description": "Projeto para preparação da impressão com cores",
  "export.3mf.note": "Para PrusaSlicer, Bambu Studio, OrcaSlicer e Cura. Cada sólido mantém-se como uma peça separada, com o seu nome e cor.",
  "export.obj.description": "Malha 3D universal",
  "export.obj.note": "Um formato de malha amplamente compatível para modelação, renderização e troca de ficheiros. As cores são guardadas nos vértices e podem ser lidas pelo Bambu Studio e pelo OrcaSlicer.",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "Preserva blocos, cilindros, esferas e cones como geometria CAD exata, assim como as peças com arestas arredondadas ou chanfradas e os sólidos importados em STEP. As roscas, molas, engrenagens e formas afuniladas, inclinadas ou torcidas também são exportadas como sólidos exatos. O texto mantém igualmente a geometria exata, letra a letra, com as curvas do próprio tipo de letra. As malhas importadas são convertidas em sólidos exatos, com planos, cilindros, cones, esferas e superfícies toroidais como faces reais; uma malha de forma livre, como uma figura, é exportada em STL.",
  "export.svg.description": "Vista de cima vetorial",
  "export.svg.note": "Exporta uma silhueta limpa da vista de cima, em milímetros, incluindo furos e contornos curvos.",
  "export.svg.noteFootprint": "Exporta apenas os contornos de contacto dos objetos com o plano de trabalho, como linhas em milímetros, para corte a laser e moldes.",
  "export.svg.noteEdges": "Exporta as arestas visíveis de cima como linhas em milímetros, cada sólido na sua cor: contornos, furos, rebaixos e gravações, com todas as áreas fechadas, para gravação a laser e plotters.",
  "export.svg.view": "Vista",
  "export.svg.viewSilhouette": "Silhueta vista de cima",
  "export.svg.viewFootprint": "Área de contacto com o plano de trabalho",
  "export.bridges": "Pontes para partes que ficariam soltas",
  "export.bridgesHint": "Uma parte dentro de um recorte, como o centro de um \"o\" ou o interior de um \"b\", fica solta quando o contorno é recortado. Pequenas pontes mantêm-na no lugar, como num molde de stencil.",
  "export.bridgeWidth": "Largura das pontes",
  "export.bridgeCount": "Pontes por parte",
  "export.svg.viewEdges": "Arestas visíveis de cima",
  "export.dxf.description": "Contorno para corte a laser",
  "export.dxf.note": "Exporta o contorno da vista de cima para serviços de corte a laser: linhas, arcos e círculos exatos na camada 0, a branco e em milímetros. Os sólidos que se tocam formam um único contorno.",
  "export.dxf.noteFootprint": "Exporta apenas os contornos de contacto dos objetos com o plano de trabalho para serviços de corte a laser: linhas, arcos e círculos exatos na camada 0, a branco e em milímetros.",
  "export.lyl.description": "Formato de projeto próprio do layerling",
  "export.lyl.note": "Preserva o projeto editável, o histórico de anular e refazer, os esboços, os grupos, os dados CAD e os ficheiros de origem importados. Os antigos ficheiros .skf também podem ser abertos e são guardados como .lyl. No Chrome e no Edge, escolhes a pasta e o nome, e Ctrl+S volta a guardar nesse ficheiro; um projeto aberto a partir de um ficheiro volta a ser guardado no mesmo.",
