  "workspace.fastMode": "Modo rápido",
  "workspace.fastModeHint": "Para computadores mais lentos: desativa as sombras, as linhas de aresta de todos os sólidos e a inércia da câmara, e apresenta a vista apenas à resolução do ecrã. As tuas definições ficam guardadas para mais tarde.",
